import { cacheTag, updateTag } from "next/cache";
import { getAllProducts } from "@/lib/db";

async function ProductListing() {
  "use cache";
  cacheTag("products");

  const products = await getAllProducts();

  return (
    <ul className="space-y-2">
      {products.map((product) => (
        <li
          key={product.id}
          className="flex justify-between rounded-lg border px-4 py-2"
        >
          <span className="font-medium">{product.name}</span>
          <span className="text-muted-foreground">${product.price}</span>
        </li>
      ))}
    </ul>
  );
}

export default function Page() {
  async function invalidateProductsCache() {
    "use server";
    updateTag("products");
  }

  return (
    <div className="container mx-auto max-w-2xl space-y-8 py-8">
      <h1 className="text-2xl font-bold">Product Listing</h1>

      <section>
        <h2 className="mb-4 text-lg font-semibold">Products</h2>
        <ProductListing />
      </section>

      <section>
        <h2 className="mb-4 text-lg font-semibold">Refresh Cache</h2>
        <p className="mb-4 text-sm text-muted-foreground">
          Submit this form to invalidate the products cache. The next render
          will fetch fresh data from the database.
        </p>
        <form action={invalidateProductsCache}>
          <button
            type="submit"
            className="rounded-md bg-primary px-4 py-2 text-primary-foreground hover:bg-primary/90"
          >
            Invalidate Products Cache
          </button>
        </form>
      </section>
    </div>
  );
}

